heets":["A262-33"]},{"ws_code":"A262-08","section_code":"F","symbol":"samples_total_count","label_de":"Probenanzahl gesamt","label_en":"Total sample count in window","data_type":"number","unit":null,"is_required":false,"enum_values":null,"validation_rules":{"raw":"eq 5 (rolling window)"},"clause_reference":"§1","description":"Total samples in the rolling 5-sample window for the 4-of-5 rule.","consumer_worksheets":["A262-33"]},{"ws_code":"A262-25","section_code":"B","symbol":"tkn_influent_high","label_de":"Hohe TKN-Zulaufkonzentration","label_en":"High influent TKN concentration","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":{"raw":"if true: detailed N-balance is required (per §4.3.4)"},"clause_reference":"§4.3.4","description":"TRUE if the influent TKN/COD ratio exceeds the values from Table 1 (typical for seasonal tourist facilities).","consumer_worksheets":["A262-28"]},{"ws_code":"A262-32","section_code":"F","symbol":"maintenance_plan_documented","label_de":"Wartungsplan dokumentiert","label_en":"Inspection/maintenance plan documented","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"true required at compliance verdict"},"clause_reference":"§6.2, §6.3, §6.4","description":"TRUE when the inspection and maintenance plan (Tables 22-24) has been documented and signed.","consumer_worksheets":["A262-33"]},{"ws_code":"A262-10","section_code":"B","symbol":"A_Fo_spez","label_de":"Spezifische Filterfläche (Oberseite)","label_en":"Specific filter area on upper surface","data_type":"number","unit":"m^2/P","is_required":true,"enum_values":null,"validation_rules":{"raw":"see Tab. 3, 4, 6, 10, 12, 14 (varies by filter type and sewer system)"},"clause_reference":"Tab. 3-14, §3.2","description":"Specific filter area as measured on the upper surface, per population equivalent.","consumer_worksheets":["A262-11","A262-12","A262-13","A262-19","A262-20","A262-22","A262-23"]},{"ws_code":"A262-10","section_code":"B","symbol":"A_Fo_min","label_de":"Mindestfilterfläche (Oberseite)","label_en":"Minimum filter area on upper surface","data_type":"number","unit":"m^2","is_required":true,"enum_values":null,"validation_rules":{"raw":"see Tab. 3-6, 8 (varies)"},"clause_reference":"Tab. 3-6, 8, §3.2","description":"Minimum required total filter area on the upper surface.","consumer_worksheets":["A262-11","A262-12","A262-13","A262-22","A262-23"]},{"ws_code":"A262-12","section_code":"B","symbol":"A_Fo1_spez","label_de":"Spez. Fläche der 1. Stufe","label_en":"Specific area of the first stage","data_type":"number","unit":"m^2/P","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 1 per Tab. 5 and Tab. 11"},"clause_reference":"Tab. 5, Tab. 11, §3.2","description":"Specific filter area of the first stage of a two-stage VF system.","consumer_worksheets":["A262-12","A262-20"]},{"ws_code":"A262-12","section_code":"B","symbol":"A_Fo2_spez","label_de":"Spez. Fläche der 2. Stufe","label_en":"Specific area of the second stage","data_type":"number","unit":"m^2/P","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 1 per Tab. 5 and Tab. 11"},"clause_reference":"Tab. 5, Tab. 11, §3.2","description":"Specific filter area of the second stage of a two-stage VF system.","consumer_worksheets":["A262-12","A262-20"]},{"ws_code":"A262-14","section_code":"B","symbol":"A_Fu_spez","label_de":"Spezifische Filterfläche (Boden)","label_en":"Specific filter area on bottom of basin","data_type":"number","unit":"m^2/P","is_required":true,"enum_values":null,"validation_rules":{"raw":">= 1 (Tab. 7, 9, 13) or >= 3 (Tab. 8)"},"clause_reference":"Tab. 7-9, 13, §3.2","description":"Specific filter area as measured on the bottom of the filter basin.","consumer_worksheets":["A262-14","A262-15","A262-16","A262-21"]},{"ws_code":"A262-14","section_code":"B","symbol":"A_Fu_min","label_de":"Mindestfilterfläche (Boden)","label_en":"Minimum filter area on bottom","data_type":"number","unit":"m^2","is_required":true,"enum_values":null,"validation_rules":{"raw":"4 (Tab. 7, 9) or 12 (Tab. 8)"},"clause_reference":"Tab. 7-9, §3.2","description":"Minimum required total filter area on the bottom of the basin.","consumer_worksheets":["A262-14","A262-15","A262-16","A262-21"]},{"ws_code":"A262-23","section_code":"B","symbol":"A_AWF_spez","label_de":"Spez. Fläche des Überlauffilters","label_en":"Specific area of the overflow filter","data_type":"number","unit":"m^2/P","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 1 (combined sewer networks only)"},"clause_reference":"Tab. 14, §3.2","description":"Specific area of the overflow filter (Überlauffilter) in lava-sand systems for combined sewers.","consumer_worksheets":["A262-23"]},{"ws_code":"A262-10","section_code":"B","symbol":"f_A_F_CSB","label_de":"Spez. CSB-Flächenbelastung (Gesamtfläche)","label_en":"Specific COD areal loading rate (total filter area)","data_type":"number","unit":"g/(m^2*d)","is_required":true,"enum_values":null,"validation_rules":{"raw":"see Tab. 3 (<=100), Tab. 10 (<=20), Tab. 14 (<=20), Tab. 15 (<=20)"},"clause_reference":"Tab. 3, 10, 14, 15, 18, §3.2","description":"Average daily specific COD (CSB) areal loading rate, calculated on the total filter area.","consumer_worksheets":["A262-12","A262-19","A262-22","A262-23","A262-24"]},{"ws_code":"A262-19","section_code":"B","symbol":"f_A_F_CSB_Betrieb","label_de":"Spez. CSB-Flächenbelastung (Fläche im Betrieb)","label_en":"Specific COD areal loading rate (operating area)","data_type":"number","unit":"g/(m^2*d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"<= 27 per Tab. 10 and Tab. 15"},"clause_reference":"Tab. 10, Tab. 15, §3.2","description":"Average daily specific COD areal loading rate on the filter area in operation (resting subsections excluded).","consumer_worksheets":["A262-19","A262-22","A262-24"]},{"ws_code":"A262-20","section_code":"B","symbol":"f_A_F01_CSB","label_de":"Spez. CSB-Flächenbelastung der 1. Stufe","label_en":"Specific COD areal loading rate of the first stage","data_type":"number","unit":"g/(m^2*d)","is_required":true,"enum_values":null,"validation_rules":{"raw":"<= 80 per Tab. 11"},"clause_reference":"Tab. 11, §3.2","description":"COD areal loading rate of the first stage of a two-stage VF in municipal WWTPs.","consumer_worksheets":["A262-20"]},{"ws_code":"A262-27","section_code":"B","symbol":"f_A_Fu_CSB","label_de":"Spez. CSB-Flächenbelastung (Boden)","label_en":"Specific COD areal loading rate (bottom)","data_type":"number","unit":"g/(m^2*d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"<= 16 per Tab. 16"},"clause_reference":"Tab. 16, §3.2","description":"COD areal loading rate on the bottom of the filter basin (HF downstream).","consumer_worksheets":["A262-15","A262-16","A262-27"]},{"ws_code":"A262-16","section_code":"B","symbol":"f_A_ANF_CSB","label_de":"Spez. CSB-Belastung (Anströmfläche)","label_en":"Specific COD loading on horizontal cross-section","data_type":"number","unit":"g/(m^2*d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"<= 200 (gravel, Tab. 9 & Tab. 16) or <= 40 (coarse sand, Tab. 16)"},"clause_reference":"Tab. 9, Tab. 16, §3.2","description":"Average daily specific COD loading rate on the horizontal cross-sectional area A_ANF of an HF.","consumer_worksheets":["A262-16","A262-21","A262-27"]},{"ws_code":"A262-14","section_code":"B","symbol":"f_V_CSB","label_de":"Spez. CSB-Volumenbelastung","label_en":"Specific COD volumetric loading rate","data_type":"number","unit":"g/(m^3*d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"<= 100 per Tab. 9 (aerated HF) and Tab. 13 (aerated VF municipal)"},"clause_reference":"Tab. 9, Tab. 13, §3.2","description":"Average daily specific COD volumetric loading rate of the filter body.","consumer_worksheets":["A262-14","A262-16","A262-21"]},{"ws_code":"A262-10","section_code":"B","symbol":"q_F_T","label_de":"Spez. hydraulische Belastung (Trockenwetter)","label_en":"Specific hydraulic loading rate, dry weather (total filter area)","data_type":"number","unit":"l/(m^2*d)","is_required":true,"enum_values":null,"validation_rules":{"raw":"see Tab. 3 (<= 250), Tab. 10 (<= 80), Tab. 15 (<= 80 or <= 120 at >=12 deg C)"},"clause_reference":"Tab. 3, 10, 14, 15, §3.2","description":"Average specific daily hydraulic loading rate over the total filter area at Q_T_d_aM.","consumer_worksheets":["A262-12","A262-19","A262-22","A262-23","A262-24"]},{"ws_code":"A262-23","section_code":"B","symbol":"q_F_T_Betrieb","label_de":"Spez. hydraulische Belastung (im Betrieb)","label_en":"Specific hydraulic loading rate, dry weather (operating area)","data_type":"number","unit":"l/(m^2*d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"<= 240 per Tab. 14 (lava sand main filter)"},"clause_reference":"Tab. 14, §3.2","description":"Average daily hydraulic loading rate over the filter area in operation, dry weather.","consumer_worksheets":["A262-23"]},{"ws_code":"A262-23","section_code":"B","symbol":"q_AWF_aM","label_de":"Spez. hydraulische Belastung des Überlauffilters","label_en":"Specific hydraulic loading rate of the overflow filter","data_type":"number","unit":"l/(m^2*d)","is_required":false,"enum_values":null,"validation_rules":{"raw":"<= 500 per Tab. 14 (overflow filter, combined sewer)"},"clause_reference":"Tab. 14, §3.2","description":"Average daily hydraulic loading rate on the overflow filter.","consumer_worksheets":["A262-23"]},{"ws_code":"A262-19","section_code":"B","symbol":"t_Sicker_min_aM","label_de":"Min. Trockenphase zwischen Beschickungen","label_en":"Average minimum time between dosing intervals","data_type":"number","unit":"h","is_required":true,"enum_values":null,"validation_rules":{"raw":"varies: >= 6 (Tab. 10, 15), >= 3 (Tab. 11), <= 4 (Tab. 13), >= 4 (Tab. 14)"},"clause_reference":"Tab. 10-15, §3.2","description":"Average annual minimum dry-phase time between successive intermittent dosing events.","consumer_worksheets":["A262-19","A262-20","A262-21","A262-22","A262-23","A262-24"]},{"ws_code":"A262-10","section_code":"B","symbol":"q_Beschickung_Fo","label_de":"Spez. Beschickungsrate (Oberseite)","label_en":"Intermittent dosing rate, upper filter surface","data_type":"number","unit":"l/(m^2*min)","is_required":true,"enum_values":null,"validation_rules":{"raw":"varies: >= 10 (Tab. 3, 11, 14) or >= 6 (Tab. 10, 12, 15)"},"clause_reference":"Tab. 3-15, §3.2","description":"Average specific hydraulic loading rate during a dosing event, measured on the upper surface of the filter.","consumer_worksheets":["A262-19","A262-20","A262-22","A262-23","A262-24"]},{"ws_code":"A262-15","section_code":"B","symbol":"q_Beschickung_Fu","label_de":"Spez. Beschickungsrate (Boden)","label_en":"Intermittent dosing rate, filter basin bottom","data_type":"number","unit":"l/(m^2*min)","is_required":false,"enum_values":null,"validation_rules":{"raw":"Tab. 8 / Tab. 13"},"clause_reference":"Tab. 8, Tab. 13, §3.2","description":"Average dosing rate measured on the bottom of the filter basin.","consumer_worksheets":["A262-15","A262-21"]},{"ws_code":"A262-10","section_code":"B","symbol":"h_Beschickung_Fo","label_de":"Beschickungshöhe (Oberseite)","label_en":"Dosing height (upper surface)","data_type":"number","unit":"l/m^2","is_required":true,"enum_values":null,"validation_rules":{"raw":"varies: 20-50 (Tab. 3), >= 10* / >= 20 (Tab. 10), >= 20 (most others)"},"clause_reference":"Tab. 3-15, §3.2","description":"Volume per dosing event per filter area, measured on the upper surface of the filter.","consumer_worksheets":["A262-19","A262-20","A262-22","A262-23","A262-24"]},{"ws_code":"A262-15","section_code":"B","symbol":"h_Beschickung_Fu","label_de":"Beschickungshöhe (Boden)","label_en":"Dosing height (bottom)","data_type":"number","unit":"l/m^2","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 20 (Tab. 8) or >= 6 (Tab. 13)"},"clause_reference":"Tab. 8, Tab. 13, §3.2","description":"Volume per dosing event per filter area, measured on the bottom of the filter basin.","consumer_worksheets":["A262-15","A262-21"]},{"ws_code":"A262-16","section_code":"B","symbol":"L_HF_min","label_de":"Mindestlänge des HF","label_en":"Minimum length of the horizontal flow filter","data_type":"number","unit":"m","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 2 per Tab. 9"},"clause_reference":"Tab. 9, §3.2","description":"Minimum filter length for an aerated horizontal flow filter as the main biological stage.","consumer_worksheets":["A262-16"]},{"ws_code":"A262-15","section_code":"B","symbol":"l_Rieselr","label_de":"Spez. Länge Rieselrohr","label_en":"Specific length of infiltration pipe per population equivalent","data_type":"number","unit":"m/P","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 6 per Tab. 8"},"clause_reference":"Tab. 8, §3.2","description":"Specific length of infiltration pipe per population equivalent in a two-layer filter trench.","consumer_worksheets":["A262-15"]},{"ws_code":"A262-15","section_code":"B","symbol":"L_Rieselr","label_de":"Einzellänge Rieselrohr","label_en":"Individual length of each infiltration pipe","data_type":"number","unit":"m","is_required":false,"enum_values":null,"validation_rules":{"raw":"<= 18 per Tab. 8"},"clause_reference":"Tab. 8, §3.2","description":"Maximum length of each infiltration pipe in a two-layer filter trench.","consumer_worksheets":["A262-15"]},{"ws_code":"A262-15","section_code":"B","symbol":"B_Rieselr","label_de":"Abstand Rieselrohre","label_en":"Horizontal spacing between infiltration pipes","data_type":"number","unit":"m","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 0.5 (Tab. 8); Tab. 17 lists >= 1 in the summary view"},"clause_reference":"Tab. 8, Tab. 17, §3.2","description":"Horizontal spacing between infiltration pipes in a two-layer filter trench.","consumer_worksheets":["A262-15"]},{"ws_code":"A262-15","section_code":"B","symbol":"B_FGR","label_de":"Bodenbreite je Rieselrohr","label_en":"Width of the trench floor per infiltration pipe","data_type":"number","unit":"m","is_required":false,"enum_values":null,"validation_rules":{"raw":">= 0.5 per Tab. 8"},"clause_reference":"Tab. 8, §3.2","description":"Width of the trench floor allocated per infiltration pipe.","consumer_worksheets":["A262-15"]}],"equations":[{"ws_code":"A262-05","equation_number":"1","formula":"Q_Tr_h_max = 24 * Q_S_d_aM / x_Q_max + Q_F + Q_R_Tr  (l/s)","input_symbols":["Q_S_d_aM","x_Q_max","Q_F","Q_R_Tr"],"output_symbol":"Q_Tr_h_max","clause_reference":"§4.1.2","description":"Maximaler stündlicher Schmutzwasserabfluss (Trennsystem)"},{"ws_code":"A262-05","equation_number":"2","formula":"Q_S_d_aM = EZ * w_s_d / 86400  (l/s)","input_symbols":["EZ","w_s_d"],"output_symbol":"Q_S_d_aM","clause_reference":"§4.1.2","description":"Mittlerer täglicher Schmutzwasserabfluss (Jahresmittel)"},{"ws_code":"A262-05","equation_number":"3","formula":"Q_F = q_F * A_E_k  (l/s)","input_symbols":["q_F","A_E_k"],"output_symbol":"Q_F","clause_reference":"§4.1.2","description":"Fremdwasser-Abfluss (Trennsystem)"},{"ws_code":"A262-05","equation_number":"4","formula":"Q_R_Tr = q_R_Tr * A_E_k  (l/s)","input_symbols":["q_R_Tr","A_E_k"],"output_symbol":"Q_R_Tr","clause_reference":"§4.1.2","description":"Unvermeidbarer Regenwasserabfluss (Trennsystem)"},{"ws_code":"A262-05","equation_number":"5","formula":"Q_F + Q_R_Tr = m * 24 * Q_S_d_aM / x_Q_max  (l/s)","input_symbols":["m_multiplier","Q_S_d_aM","x_Q_max"],"output_symbol":"Q_F + Q_R_Tr","clause_reference":"§4.1.2","description":"Kombinierter Fremd-/Regenwasser-Abfluss als Pauschalbeitrag (Trennsystem)"},{"ws_code":"A262-06","equation_number":"6","formula":"Q_M = f_S_QM * Q_S_d_aM + Q_F >= SUM(Q_Dr_RUB)  (l/s)","input_symbols":["f_S_QM","Q_S_d_aM","Q_F","Q_Dr_RUB"],"output_symbol":"Q_M","clause_reference":"§4.1.2","description":"Maximaler Mischwasser-Abfluss (Mischsystem mit Stauraumkanal-Überlauf)"},{"ws_code":"A262-06","equation_number":"7","formula":"Q_F = q_F * A_E_k  (l/s)","input_symbols":["q_F","A_E_k"],"output_symbol":"Q_F","clause_reference":"§4.1.2","description":"Fremdwasser-Abfluss (Mischsystem)"},{"ws_code":"A262-06","equation_number":"8","formula":"Q_M >= SUM(Q_Dr_RU) >= SUM(Q_krit)  (l/s)","input_symbols":["Q_Dr_RU","Q_krit"],"output_symbol":"Q_M","clause_reference":"§4.1.2","description":"Maximaler Mischwasser-Abfluss (Mischsystem mit Regenüberlauf ohne Speicher)"},{"ws_code":"A262-06","equation_number":"9","formula":"Q_T_d_aM = Q_S_d_aM + Q_F_d_aM  (m^3/d)","input_symbols":["Q_S_d_aM","Q_F_d_aM"],"output_symbol":"Q_T_d_aM","clause_reference":"§4.1.2","description":"Mittlerer täglicher Trockenwetterabfluss (Jahresmittel)"},{"ws_code":"A262-06","equation_number":"10","formula":"Q_F_d_aM = m_T_aM * Q_S_d_aM  (m^3/d)","input_symbols":["m_T_aM","Q_S_d_aM"],"output_symbol":"Q_F_d_aM","clause_reference":"§4.1.2","description":"Mittlerer täglicher Fremdwasser-Abfluss (Jahresmittel)"},{"ws_code":"A262-25","equation_number":"11","formula":"f_red = 1 - t_Reg / 12   with f_red >= 0.5","input_symbols":["t_Reg"],"output_symbol":"f_red","clause_reference":"§4.3.4","description":"Flächenreduktionsfaktor (Saisonbetrieb)"},{"ws_code":"A262-25","equation_number":"12","formula":"A_F_CSB_red = f_red * A_F_CSB  [m^2]","input_symbols":["f_red","A_F_CSB"],"output_symbol":"A_F_CSB_red","clause_reference":"§4.3.4","description":"Reduzierte Filterfläche (CSB-Bemessung)"},{"ws_code":"A262-25","equation_number":"13","formula":"for B_d_TKN / A_F_CSB_red >= B_A_TKN_zul  use: A_F_TKN_red = B_d_TKN / B_A_TKN_zul","input_symbols":["B_d_TKN","A_F_CSB_red","B_A_TKN_zul"],"output_symbol":"A_F_TKN_red","clause_reference":"§4.3.4","description":"Reduzierte Filterfläche TKN (Bedingung 1: hohe Belastung) — Verdacht auf OCR-Fehler in Quelle"},{"ws_code":"A262-25","equation_number":"14","formula":"for B_d_TKN / A_F_CSB_red < B_A_TKN_zul  use: A_F_TKN_red = B_d_TKN / B_A_TKN_zul","input_symbols":["B_d_TKN","A_F_CSB_red","B_A_TKN_zul"],"output_symbol":"A_F_TKN_red","clause_reference":"§4.3.4","description":"Reduzierte Filterfläche TKN (Bedingung 2: niedrige Belastung) — RHS verdächtig identisch zu Gl. 13"},{"ws_code":"A262-27","equation_number":"15","formula":"A_ANF = 2 * h_zu * (Q_T_d_aM * L_HF) / (k_fB * (h_zu^2 - h_ab^2))  (m^2)","input_symbols":["h_zu","Q_T_d_aM","L_HF","k_fB","h_ab"],"output_symbol":"A_ANF","clause_reference":"§4.3.6.2","description":"Erforderliche Fließquerschnittsfläche im HF-Zulauf"},{"ws_code":"A262-28","equation_number":"16","formula":"eta_DN = 1 - 1 / (1 + RV) + eta_VF","input_symbols":["RV","eta_VF"],"output_symbol":"eta_DN","clause_reference":"§4.5","description":"Wirkungsgrad der vorgeschalteten Denitrifikation (mit Rezirkulation)"},{"ws_code":"A262-29","equation_number":"17","formula":"k_fA = (d_10)^2 / 100   (m/s, with d_10 in mm)","input_symbols":["d_10"],"output_symbol":"k_fA","clause_reference":"§5.4.1","description":"Durchlässigkeitskoeffizient aus Korngröße d_10 (Beyer-Formel)"},{"ws_code":"A262-29","equation_number":"18","formula":"U = d_60 / d_10   with U < 5","input_symbols":["d_60","d_10"],"output_symbol":"U","clause_reference":"§5.4.1","description":"Ungleichförmigkeitskoeffizient des Filtermaterials"}],"compliance":[{"ws_code":"A262-01","code":"REQ-01","title_de":"Scope applicability","condition":"system_size_category IN scope_categories","description":"Project falls within DWA-A 262E scope: small WWTS (up to 50 PE) OR municipal WWTP OR seasonal WWTP OR combined WWTP with biological/polishing treatment OR greywater treatment per §1.","clause_reference":"§1"},{"ws_code":"A262-04","code":"REQ-02","title_de":"Specific wastewater generation rate","condition":"w_s_d >= 150 if municipal; w_s_d >= 75 if greywater","description":"Specific wastewater generation rate w_s,d is >= 150 l/(P*d) for municipal wastewater; >= 75 l/(P*d) for greywater.","clause_reference":"§4.1.2, §4.1.3"},{"ws_code":"A262-04","code":"REQ-03","title_de":"Peak factor for municipal wastewater","condition":"x_Q_max == 8","description":"Hourly peak factor x_Q,max = 8 h/d must be used for municipal wastewater.","clause_reference":"§4.1.2"},{"ws_code":"A262-04","code":"REQ-04","title_de":"Extraneous water and stormwater per DWA-A 118","condition":"0.05 <= q_F <= 0.15 and 0.2 <= q_R_Tr <= 0.7","description":"q_F and q_R,Tr must be determined per DWA-A 118, in the documented ranges (q_F: 0.05-0.15 l/(s*ha); q_R,Tr: 0.2-0.7 l/(s*ha)).","clause_reference":"§4.1.2"},{"ws_code":"A262-04","code":"REQ-05","title_de":"Minimum lump-sum multiplier","condition":"m_multiplier >= 1","description":"Lump-sum multiplier m >= 1 (for combined Q_F + Q_R,Tr in separate sewer networks).","clause_reference":"§4.1.2"},{"ws_code":"A262-04","code":"REQ-06","title_de":"Combined sewer factor f_S,QM","condition":"6 <= f_S_QM <= 9","description":"f_S,QM between 6 and 9 per ATV-DVWK-A 198:2003.","clause_reference":"§4.1.2"},{"ws_code":"A262-04","code":"REQ-07","title_de":"Annual extraneous-water multiplier","condition":"0.25 <= m_T_aM <= 1","description":"m_T,aM usually between 0.25 and 1.","clause_reference":"§4.1.2"},{"ws_code":"A262-04","code":"REQ-08","title_de":"Pretreatment is mandatory","condition":"pretreatment_selected != none","description":"A functioning pretreatment step per §4.2 is a prerequisite for long-term operation of any filter.","clause_reference":"§5.2"},{"ws_code":"A262-10","code":"REQ-09","title_de":"Filter dimensioning — small WWTS path","condition":"complete A262-11 through A262-17 per filter type chosen","description":"If system_size_category == small_wwts, filter dimensioning follows §4.3.1 (vertical) or §4.3.2 (horizontal aerated); summary parameters per Table 17.","clause_reference":"§4.3.1, §4.3.2, §4.4"},{"ws_code":"A262-18","code":"REQ-10","title_de":"Filter dimensioning — municipal WWTP path","condition":"complete A262-19 through A262-24 per filter type chosen","description":"If system_size_category == municipal_wwtp, filter dimensioning follows §4.3.3; summary parameters per Table 18.","clause_reference":"§4.3.3, §4.4"},{"ws_code":"A262-25","code":"REQ-11","title_de":"Seasonal operation area-reduction floor","condition":"if seasonal_operation == seasonal then f_red >= 0.5","description":"If seasonal_operation == seasonal, f_red must be >= 0.5 (per §4.3.4); applies to vertical filter with sand 0-2 mm only.","clause_reference":"§4.3.4"},{"ws_code":"A262-25","code":"REQ-12","title_de":"Greywater design rate","condition":"if wastewater_type == greywater_only then w_s_d >= 75","description":"If wastewater_type == greywater_only, design at >= 75 l/(P*d) per DWA-A 272:2014.","clause_reference":"§4.1.3"},{"ws_code":"A262-25","code":"REQ-13","title_de":"Downstream HF hydraulic check","condition":"evaluate Gl. 15","description":"For horizontal-flow downstream filter, A_ANF computed from Gl. 15 with k_fB approx. one order of magnitude below k_fA.","clause_reference":"§4.3.6.2"},{"ws_code":"A262-25","code":"REQ-14","title_de":"Upstream denitrification recirculation cap","condition":"RV <= 2 (recommended)","description":"RV > 2 yields no additional improvement in treatment performance (informative cap).","clause_reference":"§4.5"},{"ws_code":"A262-25","code":"REQ-15","title_de":"Filter media fines fraction","condition":"fines_fraction <= 2","description":"Total content of grains <63 micrometres must not exceed 2 % by mass.","clause_reference":"§5.4.1"},{"ws_code":"A262-25","code":"REQ-16","title_de":"Uniformity coefficient","condition":"U < 5","description":"U = d_60 / d_10 should be < 5.","clause_reference":"§5.4.1"},{"ws_code":"A262-25","code":"REQ-17","title_de":"Filter lining k_f requirement","condition":"if lining_type IN {mineral_seal, unsealed_subsoil} then k_f_lining <= 1e-8","description":"If a mineral seal or unsealed subsoil is used, k_f <= 1e-8 m/s must be demonstrated per DIN 18130-1 on >= 3 samples.","clause_reference":"§5.3"},{"ws_code":"A262-25","code":"REQ-18","title_de":"Geomembrane thickness","condition":"geomembrane_thickness >= 1.5 (general) or >= 1.0 (small WWTS, no welds)","description":"Geomembrane >= 1.5 mm UV-resistant polyethylene (>= 1 mm for small WWTS installations without welds).","clause_reference":"§5.3"},{"ws_code":"A262-30","code":"REQ-19","title_de":"Effluent quality - Size Class 1","condition":"effluent meets Size Class 1 thresholds in random samples","description":"BOD5 <= 40 mg/l, COD <= 150 mg/l (random samples; 4 of 5 within limits) per German Wastewater Ordinance Appendix 1 Part C.","clause_reference":"§1"},{"ws_code":"A262-30","code":"REQ-20","title_de":"Further nitrification (S_NH4)","condition":"if nitrification required: temp >= 12 °C and S_NH4 <= 10 mg/l","description":"Vertical-flow and aerated horizontal-flow filters are suitable for further nitrification (S_NH4 <= 10 mg/l) at filter-effluent water temperatures >= 12 °C.","clause_reference":"§1"},{"ws_code":"A262-30","code":"REQ-21","title_de":"Inspection and maintenance plan","condition":"maintenance_plan_documented == True","description":"Self-inspection and maintenance plan documented per §6.2 / §6.3 / §6.4 (Tables 22-24).","clause_reference":"§6.2, §6.3, §6.4"},{"ws_code":"A262-01","code":"REQ-22","title_de":"Climate suitability","condition":"climate_suitability_documented == True","description":"Design assumes Central-European climate with warm summers and cold winters (no permafrost); regions with permafrost are unsuitable.","clause_reference":"Foreword"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
